// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { BarChart } from "@/registry/erbium/charts/bar-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import StackedExample from "./variants/stacked";



import HorizontalExample from "./variants/horizontal";



const meta = {
  component: BarChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Pass one row per category and list the numeric fields to draw in `series`. Each series takes the next chart color unless it sets `color`.

```tsx
import { BarChart } from "@/registry/erbium/charts/bar-chart";

<BarChart
  ariaLabel="Visitors by month and device"
  data={visitors}
  index="month"
  series={[
    { key: "desktop", label: "Desktop" },
    { key: "mobile", label: "Mobile" },
  ]}
/>;
```

Use `stacked` to show totals and their parts, and `orientation="horizontal"` for long category names. When many categories have long names on a narrow screen, prefer horizontal bars. For parts of a whole, use a [Pie Chart](/docs/charts/pie-chart).",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof BarChart>;

export default { ...meta, title: "Charts/Bar Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  axis: boolean;
  grid: boolean;
  legend: boolean;
  orientation: "vertical" | "horizontal";
  stacked: boolean;
  tooltip: boolean;
}> = {
  argTypes: {
    axis: { control: "boolean" },
    grid: { control: "boolean" },
    legend: { control: "boolean" },
    orientation: { control: "inline-radio", options: ["vertical", "horizontal"] },
    stacked: { control: "boolean" },
    tooltip: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export const defaultProps = {
  axis: true,
  grid: true,
  legend: true,
  orientation: "vertical",
  stacked: false,
  tooltip: true,
} satisfies {
  axis: boolean;
  grid: boolean;
  legend: boolean;
  orientation: "vertical" | "horizontal";
  stacked: boolean;
  tooltip: boolean;
};

export default function BarChartPlaygroundExample(
  args: {
    axis: boolean;
    grid: boolean;
    legend: boolean;
    orientation: "vertical" | "horizontal";
    stacked: boolean;
    tooltip: boolean;
  } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <BarChart
        ariaLabel="Visitors by month and device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Stacked: Story = {
  parameters: {
    docs: {
      description: { story: "Stacked bars show each month's total and how desktop and mobile divide it. Only the outer end of each stack is rounded." },
      source: { code: "import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export default function BarChartStackedExample() {
  return (
    <div className="w-full p-4">
      <BarChart
        ariaLabel="Visitors by month, stacked by device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        stacked
        initialWidth={640}
      />
    </div>
  );
}
" },
    },
  },
  render: StackedExample,
};

export const Horizontal: Story = {
  parameters: {
    docs: {
      description: { story: "Horizontal bars list categories down the side, which leaves room for longer names. A single series hides the legend by default." },
      source: { code: "import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { browsers } from "../examples/data";

export default function BarChartHorizontalExample() {
  return (
    <div className="w-full p-4">
      <BarChart
        ariaLabel="Visitors by browser"
        data={browsers}
        index="browser"
        series={[{ key: "visitors", label: "Visitors" }]}
        orientation="horizontal"
        initialWidth={640}
      />
    </div>
  );
}
" },
    },
  },
  render: HorizontalExample,
};

import type { ChartValue } from "@tanstack/charts";
import { formatChartIndex } from "@/registry/erbium/charts/chart";

export const visitors = [
  { desktop: 186, mobile: 80, month: "January" },
  { desktop: 305, mobile: 200, month: "February" },
  { desktop: 237, mobile: 120, month: "March" },
  { desktop: 73, mobile: 190, month: "April" },
  { desktop: 209, mobile: 130, month: "May" },
  { desktop: 214, mobile: 140, month: "June" },
];

export const devices = [
  { key: "desktop", label: "Desktop" },
  { key: "mobile", label: "Mobile" },
] as const;

export const shortMonth = (value: ChartValue) => formatChartIndex(value).slice(0, 3);

export const browsers = [
  { browser: "Chrome", visitors: 275 },
  { browser: "Safari", visitors: 200 },
  { browser: "Firefox", visitors: 187 },
  { browser: "Edge", visitors: 173 },
  { browser: "Other", visitors: 90 },
];

import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { browsers } from "../examples/data";

export default function BarChartHorizontalExample() {
  return (
    <div className="w-full p-4">
      <BarChart
        ariaLabel="Visitors by browser"
        data={browsers}
        index="browser"
        series={[{ key: "visitors", label: "Visitors" }]}
        orientation="horizontal"
        initialWidth={640}
      />
    </div>
  );
}

import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export const defaultProps = {
  axis: true,
  grid: true,
  legend: true,
  orientation: "vertical",
  stacked: false,
  tooltip: true,
} satisfies {
  axis: boolean;
  grid: boolean;
  legend: boolean;
  orientation: "vertical" | "horizontal";
  stacked: boolean;
  tooltip: boolean;
};

export default function BarChartPlaygroundExample(
  args: {
    axis: boolean;
    grid: boolean;
    legend: boolean;
    orientation: "vertical" | "horizontal";
    stacked: boolean;
    tooltip: boolean;
  } = defaultProps,
) {
  return (
    <div className="w-full p-4">
      <BarChart
        ariaLabel="Visitors by month and device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        initialWidth={640}
        {...args}
      />
    </div>
  );
}

import { BarChart } from "@/registry/erbium/charts/bar-chart";
import { devices, shortMonth, visitors } from "../examples/data";

export default function BarChartStackedExample() {
  return (
    <div className="w-full p-4">
      <BarChart
        ariaLabel="Visitors by month, stacked by device"
        data={visitors}
        index="month"
        indexFormat={shortMonth}
        series={devices}
        stacked
        initialWidth={640}
      />
    </div>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);
